//! r1182 DestructiveCarrierEffectInventoryOutcomeProjection – audit-side projection of the
//! build-time destructive carrier effect inventory.
//!
//! The inventory is generated by `src/build_gate/destructive_carrier_effect_scan.rs` and
//! transported through the existing build-script include pattern. This module only reads
//! and projects it. It owns no music, selector, repair, proof or permit semantics; its rows
//! describe syntactic effect surfaces, never a musical reason for any change.

#[derive(Debug, Clone, Copy)]
pub struct StaticEffectSurfaceRow {
    pub locator: u64,
    pub surface: &'static str,
    pub physical: &'static str,
    pub reachability: &'static str,
    pub observability: &'static str,
    pub recorder: &'static str,
}

#[derive(Debug, Clone, Copy)]
pub struct StaticSinkKindRow {
    pub kind: &'static str,
    pub granularity: &'static str,
    pub call_sites: usize,
}

/// r1201 static identity coverage row of one transformation surface or file sink.
#[derive(Debug, Clone, Copy)]
pub struct StaticIdentityCoverageRow {
    pub locator: u64,
    pub owner: &'static str,
    pub surface: &'static str,
    pub physical: &'static str,
    pub reachability: &'static str,
    pub coverage: &'static str,
}

/// r1201 exact source callsite of an identity-minting typed entry.
#[derive(Debug, Clone, Copy)]
pub struct StaticMintingSiteRow {
    pub path: &'static str,
    pub line: usize,
    pub entry: u64,
}

/// r1201 syntactic nominal-gate inventory row.
#[derive(Debug, Clone, Copy)]
pub struct StaticNominalGateRow {
    pub rule: &'static str,
    pub owner: &'static str,
    pub locator: u64,
    pub reachability: &'static str,
    pub subject: &'static str,
    pub linked_sites: &'static [(&'static str, usize)],
}

include!(env!("ETUSCHLOPF_DESTRUCTIVE_CARRIER_EFFECT_INVENTORY_RS"));

const UNRESOLVED_GRANULARITY: &str = "SINGLE_OR_BLOCK_UNRESOLVED";

/// Static region granularity for a runtime recorder kind. Unknown kinds stay unresolved.
pub fn static_kind_granularity(kind: &str) -> &'static str {
    RENDER_SINK_KIND_ROWS
        .iter()
        .find(|row| row.kind == kind)
        .map_or(UNRESOLVED_GRANULARITY, |row| row.granularity)
}

pub fn append_static_effect_inventory(out: &mut String) {
    let count = |matches: &dyn Fn(&StaticEffectSurfaceRow) -> bool| {
        DESTRUCTIVE_EFFECT_SURFACES.iter().filter(|row| matches(row)).count()
    };
    out.push_str(
        "DestructiveCarrierEffectInventoryContract: build-time syntactic inventory of typed effect owners, carrier-markup XML rebuild paths and persisting file sinks; no function name is read as a musical reason; region granularity is SINGLE only for one reachable transformation surface on a persisted-read input, BLOCK only for at least two straight-line surfaces before the sink, otherwise SINGLE_OR_BLOCK_UNRESOLVED.\n",
    );
    out.push_str(&format!(
        "DestructiveCarrierEffectInventory: SourceFiles {}; FunctionsScanned {}; Surfaces {}; TypedAuthority {}; XmlRebuild {}; FileSinks {}; Productive {}; Retired {}; KeepaliveOnly {}; ObservabilityExact {}; ObservabilityBlock {}; ObservabilityUnknown {}; NotInstrumented {}; RecorderTracedSinks {}; RecorderUnresolvedSinks {}; UntracedProductiveFileSinks {}; Fingerprint FNV1A64:{:016x}.\n",
        DESTRUCTIVE_EFFECT_SCAN_SOURCE_FILES,
        DESTRUCTIVE_EFFECT_SCAN_FUNCTIONS,
        DESTRUCTIVE_EFFECT_SURFACES.len(),
        count(&|row| row.surface == "TYPED_AUTHORITY"),
        count(&|row| row.surface == "XML_REBUILD"),
        count(&|row| row.surface == "FILE_SINK"),
        count(&|row| row.reachability == "PRODUCTIVE"),
        count(&|row| row.reachability == "RETIRED"),
        count(&|row| row.reachability == "KEEPALIVE_ONLY"),
        count(&|row| row.observability == "EXACT"),
        count(&|row| row.observability == "BLOCK"),
        count(&|row| row.observability == "UNKNOWN"),
        count(&|row| row.observability == "NOT_INSTRUMENTED"),
        count(&|row| row.recorder == "YES"),
        count(&|row| row.recorder == "UNRESOLVED"),
        DESTRUCTIVE_EFFECT_UNTRACED_FILE_SINKS,
        DESTRUCTIVE_EFFECT_INVENTORY_FNV1A64,
    ));
    for row in DESTRUCTIVE_EFFECT_SURFACES {
        out.push_str(&format!(
            "DestructiveCarrierEffectSurface: locator {:016x}; surface {}; physical {}; reachability {}; observability {}; recorder {}.\n",
            row.locator, row.surface, row.physical, row.reachability, row.observability, row.recorder
        ));
    }
    for row in RENDER_SINK_KIND_ROWS {
        out.push_str(&format!(
            "RenderSinkKindGranularity: kind {}; granularity {}; call_sites {}.\n",
            row.kind, row.granularity, row.call_sites
        ));
    }
}

#[cfg(test)]
#[path = "../build_gate/destructive_carrier_effect_scan.rs"]
mod effect_scan_instrument;

#[cfg(test)]
mod tests {
    use super::effect_scan_instrument::{
        effect_inventory_generated_source, observe_effect_inventory_roots,
        observe_effect_inventory_text, EffectInventory, COVERAGE_MISSING, COVERAGE_PRESENT,
        COVERAGE_RETIRED, GRANULARITY_BLOCK, GRANULARITY_SINGLE, GRANULARITY_UNRESOLVED,
        RULE_CONSTANT_OPEN_PARAMETER, RULE_CONSTANT_TRUE_FIELD, RULE_CONSTANT_ZERO_FIELD,
        RULE_LITERAL_COORDINATE_TABLE, RULE_LITERAL_MEASURE_BINDING,
    };

    // Synthetic, corpus-independent sources. Effect-owner names live only inside string
    // fixtures; the test functions themselves carry neutral names.
    const OWNER_FILE: &str = "src/structural_write_authority/synthetic_owner.rs";
    const OWNER_SOURCE: &str = r#"
pub fn first_effect_surface(xml: &str) -> String {
    let mut out = xml.to_string();
    out.replace_range(0..0, "<forward><duration>1</duration></forward>");
    out
}
pub fn second_effect_surface(xml: &str) -> String {
    let mut out = xml.to_string();
    out.insert_str(0, "<note print-object=\"no\"/>");
    out
}
pub fn persisting_file_sink(path: &std::path::Path, payload: &str) -> std::io::Result<()> {
    let before = capture_before(path);
    std::fs::write(path, payload)?;
    crate::audit_only::writer_trace::record_after("synthetic_sink_kind", path, before.as_deref(), payload);
    Ok(())
}
"#;

    fn pipeline_source(region_body: &str) -> String {
        format!(
            r#"
pub(super) fn run() -> i32 {{
    region(&reader.read_or_fallback(""));
    0
}}
fn region(xml: &str) {{
{region_body}
    let _ = persisting_file_sink(path, &payload);
}}
fn orphan(xml: &str) -> String {{
    second_effect_surface(xml)
}}
"#
        )
    }

    fn inventory_for(region_body: &str) -> EffectInventory {
        observe_effect_inventory_text(&[
            (OWNER_FILE.to_string(), OWNER_SOURCE.to_string()),
            ("src/pipeline.rs".to_string(), pipeline_source(region_body)),
        ])
    }

    fn kind_granularity(inventory: &EffectInventory, kind: &str) -> String {
        inventory
            .sink_kinds
            .iter()
            .find(|row| row.kind == kind)
            .map(|row| row.granularity.clone())
            .unwrap_or_default()
    }

    #[test]
    fn instrument_resolves_one_surface_region_as_single_transformation() {
        let inventory = inventory_for("    let payload = first_effect_surface(xml);");
        assert_eq!(kind_granularity(&inventory, "synthetic_sink_kind"), GRANULARITY_SINGLE);
        let exact = inventory
            .surfaces
            .iter()
            .filter(|row| row.observability == "EXACT")
            .count();
        assert_eq!(exact, 1);
    }

    #[test]
    fn instrument_resolves_two_straight_line_surfaces_as_block() {
        let inventory = inventory_for(
            "    let staged = first_effect_surface(xml);\n    let payload = second_effect_surface(&staged);",
        );
        assert_eq!(kind_granularity(&inventory, "synthetic_sink_kind"), GRANULARITY_BLOCK);
    }

    #[test]
    fn instrument_keeps_conditional_second_surface_unresolved() {
        let inventory = inventory_for(
            "    let staged = first_effect_surface(xml);\n    let payload = if flag { second_effect_surface(&staged) } else { staged };",
        );
        assert_eq!(kind_granularity(&inventory, "synthetic_sink_kind"), GRANULARITY_UNRESOLVED);
    }

    #[test]
    fn instrument_classifies_surfaces_and_recorder_state() {
        let inventory = inventory_for("    let payload = first_effect_surface(xml);");
        let physical = |effect: &str| {
            inventory
                .surfaces
                .iter()
                .any(|row| row.physical == effect && row.reachability == "PRODUCTIVE")
        };
        assert!(physical("REST_TO_FORWARD"));
        assert!(physical("WHOLE_FILE_WRITE"));
        let sink = inventory
            .surfaces
            .iter()
            .find(|row| row.surface == "FILE_SINK")
            .expect("synthetic sink inventoried");
        assert_eq!(sink.recorder, "YES");
        assert_eq!(inventory.untraced_file_sinks, 0);
        let second = inventory
            .surfaces
            .iter()
            .find(|row| row.physical == "HIDE_CARRIER")
            .expect("second surface inventoried");
        assert_eq!(second.reachability, "RETIRED");
    }

    // r1201 synthetic coverage and nominal-gate controls.
    const COVERAGE_OWNER_FILE: &str = "src/structural_write_authority/synthetic_coverage_owner.rs";
    const COVERAGE_OWNER_SOURCE: &str = r#"
pub fn identity_bearing_surface(source: &str, edits: Vec<(usize, usize, String)>) -> Option<String> {
    let attribution = DestructiveEditBatchAttribution::begin_destructive_edit_batch_attribution(edits.len());
    let mut out = source.to_string();
    out.replace_range(0..0, "");
    drop(attribution);
    Some(out)
}
pub fn identity_free_surface(source: &str) -> String {
    let mut out = source.to_string();
    out.insert_str(0, "<x/>");
    out
}
pub fn unreached_surface(source: &str) -> String {
    let mut out = source.to_string();
    out.insert_str(0, "<y/>");
    out
}
"#;
    const COVERAGE_PIPELINE_SOURCE: &str = r#"
#[cfg(test)]
fn helper_for_tests() -> bool {
    true
}
pub(super) fn run() -> i32 {
    let first = crate::structural_write_authority::identity_bearing_surface("", Vec::new());
    let second = identity_free_surface("");
    drop((first, second));
    0
}
fn orphan() -> String {
    unreached_surface("")
}
fn modulate() -> usize {
    3
}
"#;

    #[test]
    fn instrument_classifies_identity_coverage_from_minting_owner_closure() {
        let inventory = observe_effect_inventory_text(&[
            (COVERAGE_OWNER_FILE.to_string(), COVERAGE_OWNER_SOURCE.to_string()),
            ("src/pipeline.rs".to_string(), COVERAGE_PIPELINE_SOURCE.to_string()),
        ]);
        let coverage_of = |name: &str| {
            inventory
                .identity_coverage
                .iter()
                .find(|row| row.owner.ends_with(name))
                .map(|row| row.coverage.clone())
                .unwrap_or_default()
        };
        assert_eq!(coverage_of("::identity_bearing_surface"), COVERAGE_PRESENT);
        assert_eq!(coverage_of("::identity_free_surface"), COVERAGE_MISSING);
        assert_eq!(coverage_of("::unreached_surface"), COVERAGE_RETIRED);
        let expected_line = COVERAGE_PIPELINE_SOURCE
            .lines()
            .position(|line| line.contains("identity_bearing_surface("))
            .map(|index| index + 1)
            .unwrap_or_default();
        assert_eq!(inventory.minting_sites.len(), 1);
        assert_eq!(inventory.minting_sites[0].path, "src/pipeline.rs");
        assert_eq!(inventory.minting_sites[0].line, expected_line);
        assert_ne!(inventory.coverage_fingerprint, 0);
    }

    const GATE_PIPELINE_SOURCE: &str = r#"
pub(super) fn run() -> i32 {
    let a = coordinate_table(0);
    let b = coordinate_binding();
    let c = gated_trial(true);
    let d = gated_trial(true);
    let e = open_or_closed(true) + open_or_closed(false);
    let f = check_outcome_trial() + counted_trial() + event_flag_trial();
    (a + b + c + d + e + f) as i32
}
fn coordinate_table(scope: usize) -> usize {
    let rows = [(3_usize, 96_i64, 71_i32), (5_usize, 0_i64, 64_i32)];
    let mut hits = 0;
    for (row_scope, _, _) in rows {
        if row_scope == scope {
            hits += 1;
        }
    }
    hits
}
fn coordinate_binding() -> usize {
    let probe = Probe { measure: 12, staff: 2 };
    let first = Probe { measure: 1, staff: 1 };
    probe.staff + first.staff
}
fn gated_trial(user_gate_open: bool) -> usize {
    usize::from(user_gate_open)
}
fn open_or_closed(user_gate_open: bool) -> usize {
    usize::from(user_gate_open)
}
fn check_outcome_trial() -> usize {
    let mut trial = Trial::default();
    trial.boundary_invariant = true;
    usize::from(trial.ready && trial.boundary_invariant)
}
fn counted_trial() -> usize {
    let trial = Trial { contradictions: 0, observed: 0, ..Trial::default() };
    let mut other = Trial::default();
    other.observed += 1;
    usize::from(trial.contradictions == 0 && other.observed == 0)
}
fn event_flag_trial() -> usize {
    let mut trial = Trial::default();
    trial.stem_added = true;
    usize::from(trial.ready && trial.stem_added)
}
"#;

    #[test]
    fn instrument_inventories_nominal_gate_rules_with_negative_controls() {
        let inventory = observe_effect_inventory_text(&[(
            "src/pipeline.rs".to_string(),
            GATE_PIPELINE_SOURCE.to_string(),
        )]);
        let flagged = |rule: &str, owner: &str, subject: &str| {
            inventory.nominal_gates.iter().any(|row| {
                row.rule == rule
                    && row.owner.ends_with(owner)
                    && row.subject == subject
                    && row.reachability == "PRODUCTIVE"
            })
        };
        assert!(flagged(RULE_LITERAL_COORDINATE_TABLE, "::coordinate_table", "-"));
        assert!(flagged(RULE_LITERAL_MEASURE_BINDING, "::coordinate_binding", "-"));
        assert!(flagged(RULE_CONSTANT_OPEN_PARAMETER, "::gated_trial", "user_gate_open"));
        assert!(!flagged(RULE_CONSTANT_OPEN_PARAMETER, "::open_or_closed", "user_gate_open"));
        assert!(flagged(RULE_CONSTANT_TRUE_FIELD, "::check_outcome_trial", "boundary_invariant"));
        assert!(!flagged(RULE_CONSTANT_TRUE_FIELD, "::event_flag_trial", "stem_added"));
        assert!(flagged(RULE_CONSTANT_ZERO_FIELD, "::counted_trial", "contradictions"));
        assert!(!flagged(RULE_CONSTANT_ZERO_FIELD, "::counted_trial", "observed"));
        assert_eq!(inventory.nominal_gates.len(), 5);
    }

    #[test]
    fn instrument_projects_generated_source_and_scans_directories() {
        let inventory = inventory_for("    let payload = first_effect_surface(xml);");
        let generated = effect_inventory_generated_source(&inventory);
        assert!(generated.contains("pub const RENDER_SINK_KIND_ROWS"));
        assert!(generated.contains("pub const IDENTITY_COVERAGE_ROWS"));
        assert!(generated.contains("pub const IDENTITY_MINTING_SITES"));
        assert!(generated.contains("pub const NOMINAL_GATE_ROWS"));
        assert!(generated.contains("synthetic_sink_kind"));
        assert_ne!(inventory.fingerprint, 0);
        assert!(inventory.source_files == 2 && inventory.functions_scanned >= 5);

        let root = std::env::temp_dir().join(format!(
            "etuschlopf_effect_scan_{}_{}",
            std::process::id(),
            inventory.fingerprint
        ));
        let owner_dir = root.join("src/structural_write_authority");
        std::fs::create_dir_all(&owner_dir).expect("synthetic tree");
        std::fs::write(owner_dir.join("synthetic_owner.rs"), OWNER_SOURCE).expect("owner file");
        std::fs::write(
            root.join("src/pipeline.rs"),
            pipeline_source("    let payload = first_effect_surface(xml);"),
        )
        .expect("pipeline file");
        let scanned = observe_effect_inventory_roots(&root, &[&root.join("src")]).expect("scan");
        let _ = std::fs::remove_dir_all(&root);
        assert_eq!(scanned.fingerprint, inventory.fingerprint);
    }
}
